"""Independent, spec-driven reference parser over materialised bytes."""
MAX = (1 << 63) - 1
TOKEN_CHARS = set(b"!#$%&'*+.^_`|~0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-")
VISIBLE = set(range(0x21, 0x7f))
FIELD_OK = {0x09} | set(range(0x20, 0x7f))
HEX = set(b'0123456789abcdefABCDEF')
DIGITS = set(b'0123456789')


class Incomplete(Exception): pass
class Syntax_(Exception): pass


def fp(data):
    h = 0
    for b in data:
        h = (h * 257 + b + 1) & ((1 << 64) - 1)
    return {'n': len(data), 'h': '%016x' % h}


EMPTY = {'n': 0, 'h': '0' * 16}


class R:
    def __init__(self, data, budget):
        self.d = data
        self.pos = 0
        self.b = budget

    def line(self, chunk=False):
        d = self.d
        pos = self.pos
        idx = d.find(b'\n', pos)
        if idx < 0:
            if len(d) - pos <= 8193:
                raise Incomplete()
            raise Syntax_()
        if idx - pos > 8193:
            raise Syntax_()
        if idx == pos or d[idx - 1] != 0x0d:
            raise Syntax_()
        self.pos = idx + 1
        if chunk:
            self.b['chunk'] += 1
            if self.b['chunk'] > 40000:
                raise ValueError('budget')
        return d[pos:idx - 1]


def fields_block(r, block):
    out = []
    while True:
        line = r.line()
        if not line:
            block += 2
            if block > 65536:
                raise Syntax_()
            return out, block
        c = line.find(b':')
        if c <= 0:
            raise Syntax_()
        nm, vl = line[:c], line[c + 1:]
        if not nm or not all(x in TOKEN_CHARS for x in nm):
            raise Syntax_()
        if not all(x in FIELD_OK for x in vl):
            raise Syntax_()
        out.append((nm, vl.strip(b' \t')))
        block += len(line) + 2
        if block > 65536 or len(out) > 128:
            raise Syntax_()


def encode_fields(fields):
    out = [len(fields).to_bytes(8, 'big')]
    for n, v in fields:
        out.append(len(n).to_bytes(8, 'big')); out.append(n)
        out.append(len(v).to_bytes(8, 'big')); out.append(v)
    return b''.join(out)


def framing_of(fields):
    cls = [v for n, v in fields if n.lower() == b'content-length']
    tes = [v for n, v in fields if n.lower() == b'transfer-encoding']
    if tes:
        if len(tes) != 1 or cls:
            raise Syntax_()
        if tes[0].lower() != b'chunked':
            raise Syntax_()
        return 'chunked', None
    if cls:
        val = None
        for v in cls:
            for m in v.split(b','):
                m = m.strip(b' \t')
                if not m or not all(x in DIGITS for x in m):
                    raise Syntax_()
                n = int(m)
                if n > MAX:
                    raise Syntax_()
                if val is None:
                    val = n
                elif n != val:
                    raise Syntax_()
        return 'length', val
    return 'none', 0


def parse(data, budget):
    r = R(data, budget)
    out = []
    error = None
    while r.pos < len(data):
        start = r.pos
        try:
            line = r.line()
            parts = line.split(b' ')
            if len(parts) != 3:
                raise Syntax_()
            method, target, version = parts
            if not method or not all(x in TOKEN_CHARS for x in method):
                raise Syntax_()
            if not target or not all(x in VISIBLE for x in target):
                raise Syntax_()
            if version != b'HTTP/1.1':
                raise Syntax_()
            fields, _ = fields_block(r, len(line) + 2)
            mode, declared = framing_of(fields)
            trailers = []
            if mode == 'none':
                body = EMPTY
            elif mode == 'length':
                if len(data) - r.pos < declared:
                    raise Incomplete()
                body = fp(data[r.pos:r.pos + declared]) if declared else EMPTY
                r.pos += declared
            else:
                acc = b''
                while True:
                    sl = r.line(chunk=True)
                    semi = sl.find(b';')
                    if semi < 0:
                        sz, sfx = sl, None
                    else:
                        sz, sfx = sl[:semi], sl[semi + 1:]
                    if not sz or not all(x in HEX for x in sz):
                        raise Syntax_()
                    if sfx is not None and not all(x in FIELD_OK for x in sfx):
                        raise Syntax_()
                    size = int(sz, 16)
                    if size > MAX:
                        raise Syntax_()
                    if size == 0:
                        trailers, _ = fields_block(r, 0)
                        for n, _v in trailers:
                            if n.lower() in (b'host', b'content-length', b'transfer-encoding'):
                                raise Syntax_()
                        break
                    if len(data) - r.pos < size:
                        raise Incomplete()
                    acc += data[r.pos:r.pos + size]
                    r.pos += size
                    if len(data) - r.pos < 2:
                        raise Incomplete()
                    if data[r.pos:r.pos + 2] != b'\r\n':
                        raise Syntax_()
                    r.pos += 2
                body = fp(acc)
        except Incomplete:
            error = {'kind': 'incomplete', 'offset': start}
            break
        except Syntax_:
            error = {'kind': 'syntax', 'offset': start}
            break
        budget['requests'] += 1
        if budget['requests'] > 20000:
            raise ValueError('budget')
        hosts = [v for n, v in fields if n.lower() == b'host']
        host = hosts[0].lower() if len(hosts) == 1 else b''
        out.append({'start': start, 'end': r.pos, 'method': fp(method),
                    'target': fp(target),
                    'host': fp(host) if len(hosts) == 1 else EMPTY,
                    'host_count': len(hosts), 'headers': fp(encode_fields(fields)),
                    'body': body, 'trailers': fp(encode_fields(trailers)),
                    'framing': mode})
    return out, error
